import{_ as i,c as a,aU as e,a as t}from"./chunks/framework.DP-R0N-M.js";const k=JSON.parse('{"title":"05-搜索引擎搜索的小技巧","description":"","frontmatter":{},"headers":[],"relativePath":"note/stationmaster/seo/05-搜索引擎搜索的小技巧.md","filePath":"note/stationmaster/seo/05-搜索引擎搜索的小技巧.md","lastUpdated":1762087769000}'),n={name:"note/stationmaster/seo/05-搜索引擎搜索的小技巧.md"};function l(h,s,p,d,r,o){return t(),a("div",null,[...s[0]||(s[0]=[e('<h1 id="_05-搜索引擎搜索的小技巧" tabindex="-1">05-搜索引擎搜索的小技巧 <a class="header-anchor" href="#_05-搜索引擎搜索的小技巧" aria-label="Permalink to &quot;05-搜索引擎搜索的小技巧&quot;">​</a></h1><h2 id="site-命令" tabindex="-1">site 命令 <a class="header-anchor" href="#site-命令" aria-label="Permalink to &quot;site 命令&quot;">​</a></h2><p>site 命令用于限制搜索结果只显示特定网站的页面，例如：<code>site:blog.share888.top SEO</code>，如下图：</p><h2 id="intitle-命令" tabindex="-1">intitle 命令 <a class="header-anchor" href="#intitle-命令" aria-label="Permalink to &quot;intitle 命令&quot;">​</a></h2><p>intitle 命令用于限制搜索结果只显示包含特定关键词在标题中的页面，例如：<code>intitle:SEO</code>，例如：</p><h2 id="inurl-命令" tabindex="-1">inurl 命令 <a class="header-anchor" href="#inurl-命令" aria-label="Permalink to &quot;inurl 命令&quot;">​</a></h2><p>假设你想找关于“人工智能”主题的博客文章，并且希望这些文章的URL中包含“blog”这个单词，以确保它们确实是博客文章。你可以这样构建搜索请求：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">人工智能</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inurl:blog</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="or-命令" tabindex="-1">OR 命令 <a class="header-anchor" href="#or-命令" aria-label="Permalink to &quot;OR  命令&quot;">​</a></h2><p>假设你对“机器学习”和“深度学习”都感兴趣，但你不想分开两次搜索，可以通过以下方式一次性完成：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">机器学习</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> OR</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 深度学习</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="命令" tabindex="-1">- 命令 <a class="header-anchor" href="#命令" aria-label="Permalink to &quot;- 命令&quot;">​</a></h2><p>假设你在搜索“苹果”时，主要对水果感兴趣，而不希望看到与科技公司“苹果”（Apple Inc.）相关的信息。你可以使用 - 命令来排除包含“公司”或“手机”等关键词的网页。搜索请求可以这样构建：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">苹果</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -公司</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -手机</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="双引号-命令" tabindex="-1">双引号 命令 <a class="header-anchor" href="#双引号-命令" aria-label="Permalink to &quot;双引号 命令&quot;">​</a></h2><p>假设你要查找关于<code>敲代码的卡卡罗特</code>的具体信息，希望搜索结果中包含这个完整的名称，可以使用双引号来实现：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">&quot;敲代码的卡卡罗特&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="搜索个人博客内容" tabindex="-1">搜索个人博客内容 <a class="header-anchor" href="#搜索个人博客内容" aria-label="Permalink to &quot;搜索个人博客内容&quot;">​</a></h2><p>方法1 通过 -site: 排除常见非个人博客的域名（如知乎、CSDN、简书等），保留独立域名或博客平台子域名：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">&quot;idea破解&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -site:zhihu.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -site:csdn.net</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -site:jianshu.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -site:weixin.qq.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -site:bilibili.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -site:juejin.cn</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>方法 2：限定网址包含 /blog/ 或 blog 子域名</p><p>许多个人博客的网址路径包含 /blog/ 或使用子域名 blog.xxx.com：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">&quot;idea破解&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inurl:/blog/</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> OR</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inurl:blog.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>注意：<code>inurl</code> 并不会严格按照<code>/blog/</code>的路径，其实是包含关系，并不严谨，不过还是能帮我们筛选出符合要求的网页.</p><p><code>inurl:/blog/</code> 和 <code>inurl:blog</code> 功能一样！！！</p><p>分享一个我常用的</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">软考系统架构设计师</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inurl:/blog/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -site:csdn.net</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -site:zhihu.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -site:51cto.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -site:sina.com.cn</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -site:oschina.net</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div>',27)])])}const u=i(n,[["render",l]]);export{k as __pageData,u as default};
